import { frameworkTracer } from "./tracer.js";
//#region src/server/app-fetch-tracing.ts
function createAppFetchSpanDescriptor(input, init) {
	let url;
	try {
		url = new URL(input instanceof Request ? input.url : input);
		url.username = "";
		url.password = "";
	} catch {}
	const fetchUrl = url?.href ?? "";
	const method = init?.method?.toUpperCase() || "GET";
	const name = [
		"fetch",
		method,
		fetchUrl
	].filter(Boolean).join(" ");
	return {
		attributes: {
			"http.method": method,
			"http.url": fetchUrl,
			"net.peer.name": url?.hostname,
			"net.peer.port": url?.port || void 0
		},
		kind: "client",
		name,
		type: "AppRender.fetch"
	};
}
function traceAppFetch(input, init, callback) {
	if (process.env.NEXT_OTEL_FETCH_DISABLED === "1") return callback();
	return frameworkTracer.trace(createAppFetchSpanDescriptor(input, init), async (span) => {
		const response = await callback(span);
		span.setAttribute("http.status_code", response.status);
		return response;
	});
}
//#endregion
export { createAppFetchSpanDescriptor, traceAppFetch };
